import numpy as np
from rdkit import Chem
from rdkit.Chem import AllChem
p=np.loadtxt('optimised.xyz',skiprows=2,usecols=(1,2,3));s=[x.split()[0] for x in open('optimised.xyz').readlines()[2:]]
for i in [10,15,16,2,3,35,36,54]: print('Rh-'+str(i),np.linalg.norm(p[0]-p[i]))
for offset,smi in [(1,'CC1=C(c2ccccc2)c2ccccc2[cH-]1'),(30,'CC(C)(C)C(=O)[O-]'),(46,'O=C(OCC(Cl)(Cl)Cl)N[C@@H]1CCC2=CC=CC=C2C1')]:
 m=Chem.AddHs(Chem.MolFromSmiles(smi));c=Chem.Conformer(m.GetNumAtoms())
 for i in range(m.GetNumAtoms()):c.SetAtomPosition(i,p[i+offset])
 m.AddConformer(c);Chem.AssignAtomChiralTagsFromStructure(m,replaceExistingTags=True);Chem.AssignStereochemistry(m,cleanIt=True,force=True)
 for a in m.GetAtoms():
  if a.HasProp('_CIPCode'): print('stereo',a.GetIdx()+offset,a.GetProp('_CIPCode'))
 for b in m.GetBonds():
  i=b.GetBeginAtomIdx()+offset;j=b.GetEndAtomIdx()+offset;d=np.linalg.norm(p[i]-p[j])
  if d>1.9 or d<.9:print('bond odd',i,j,s[i],s[j],d)
 for j in range(offset,offset+m.GetNumAtoms()):
  if np.linalg.norm(p[j]-p[0])<1.95: print('short Rh',j,s[j],np.linalg.norm(p[j]-p[0]))
